VALUES ('anmeldung-a1', $chunk${"t":"Ein Kind anmelden – A1","d":"Der Lernende kann im Sekretariat ein Kind anmelden, persönliche Daten nennen, einfache Unterlagen verstehen und nach Schulbeginn fragen.","s":[["Guten Tag. Ich möchte mein Kind anmelden.","Anliegen nennen"],["Wie heißt Ihr Kind? – Amir Hadžić.","Name nennen"],["Wann ist Ihr Kind geboren?","Geburtsdatum verstehen"],["Wie ist Ihre Adresse?","Adresse nennen"],["Wie ist Ihre Telefonnummer?","Kontaktdaten"],["Bitte füllen Sie dieses Formular aus.","Anweisung"],["Haben Sie Ihren Ausweis dabei? – Ja.","Dokument"],["Wir brauchen die Geburtsurkunde.","Unterlage"],["Haben Sie einen Adressnachweis?","Unterlage"],["Bitte unterschreiben Sie hier.","Anweisung"],["Einen Moment, ich prüfe die Unterlagen.","Warteformel"],["Wann beginnt die Schule?","nach Beginn fragen"],["Welche Klasse besucht mein Kind?","Klasse erfragen"],["Hier ist die Liste für Schulmaterial.","Information erhalten"],["Danke für die Informationen. Auf Wiedersehen.","Abschluss"]],"v":[["die Anmeldung","die Anmeldungen","Registrierung","Die Anmeldung ist im Sekretariat."],["das Kind","die Kinder","Sohn/Tochter","Ich möchte mein Kind anmelden."],["das Sekretariat","die Sekretariate","Schulverwaltung","Ich gehe ins Sekretariat."],["das Formular","die Formulare","Dokument zum Ausfüllen","Bitte füllen Sie das Formular aus."],["der Name","die Namen","Personenname","Wie ist der Name Ihres Kindes?"],["das Geburtsdatum","die Geburtsdaten","Datum der Geburt","Bitte nennen Sie das Geburtsdatum."],["die Adresse","die Adressen","Wohnadresse","Wie ist Ihre Adresse?"],["die Telefonnummer","die Telefonnummern","Telefonkontakt","Wie ist Ihre Telefonnummer?"],["der Ausweis","die Ausweise","Identitätsdokument","Ich habe meinen Ausweis dabei."],["die Geburtsurkunde","die Geburtsurkunden","Dokument zur Geburt","Wir brauchen die Geburtsurkunde."],["der Adressnachweis","die Adressnachweise","Dokument zur Adresse","Haben Sie einen Adressnachweis?"],["die Unterschrift","die Unterschriften","Signatur","Hier fehlt die Unterschrift."],["die Unterlage","die Unterlagen","Dokument","Sind alle Unterlagen vollständig?"],["die Klasse","die Klassen","Schulklasse","Welche Klasse besucht mein Kind?"],["der Schulbeginn","—","Beginn des Schuljahres","Wann ist Schulbeginn?"],["die Liste","die Listen","Aufstellung","Hier ist die Materialliste."],["anmelden","—","registrieren","Ich möchte mein Kind anmelden."],["ausfüllen","—","Formular ergänzen","Bitte füllen Sie das Formular aus."],["unterschreiben","—","signieren","Bitte hier unterschreiben."],["zeigen","—","vorlegen","Bitte zeigen Sie Ihren Ausweis."],["brauchen","—","benötigen","Welche Unterlagen brauchen Sie?"],["vollständig","—","alles vorhanden","Die Unterlagen sind vollständig."],["fehlen","—","nicht vorhanden sein","Eine Unterschrift fehlt."],["beginnen","—","starten","Die Schule beginnt im September."],["besuchen","—","in eine Klasse/Schule gehen","Mein Kind besucht die erste Klasse."]],"p":["1. Wo ist das Sekretariat? Das Sekretariat ist neben dem Haupteingang.","2. Wo fülle ich das Formular aus? Sie können das Formular am Tisch ausfüllen.","3. Wo unterschreibe ich? Bitte unterschreiben Sie unten auf dem Formular.","4. Wo liegen die Unterlagen? Die Unterlagen liegen auf dem Schreibtisch.","5. Wo wartet mein Kind? Ihr Kind kann im Wartebereich warten.","6. Wo bekomme ich die Materialliste? Die Materialliste bekommen Sie im Sekretariat."],"dgs":[[1,"Mutter","Guten Tag. Ich möchte mein Kind anmelden.","Anmeldung im Sekretariat"],[1,"Mitarbeiterin","Gerne. Wie heißt Ihr Kind?","Anmeldung im Sekretariat"],[1,"Mutter","Amir Hadžić.","Anmeldung im Sekretariat"],[1,"Mitarbeiterin","Wann ist Amir geboren?","Anmeldung im Sekretariat"],[1,"Mutter","Am 12. Mai 2019.","Anmeldung im Sekretariat"],[1,"Mitarbeiterin","Bitte füllen Sie dieses Formular aus.","Anmeldung im Sekretariat"],[2,"Mutter","Welche Unterlagen brauchen Sie?","Unterlagen und Schulbeginn"],[2,"Mitarbeiterin","Den Ausweis und die Geburt